import { createSdkMcpServer, tool } from "@anthropic-ai/claude-agent-sdk";
import { z } from "zod";

const PAGES: Record<string, string> = {
  sandbox: "brain/sandbox-sizes.md: a lite VM has 4 vCPU",
  pool: "brain/warm-pool.md: stopped VMs wait in the pool and start in about a minute",
};

export const kbSearch = tool(
  "kb_search",
  "Search the team's knowledge base. Returns the best page and one key fact.",
  { question: z.string().describe("What you want to know, in plain words") },
  async ({ question }) => {
    const hit = Object.entries(PAGES).find(([word]) => question.toLowerCase().includes(word));
    if (!hit) return { content: [{ type: "text", text: `No page matches "${question}".` }], isError: true };
    return { content: [{ type: "text", text: hit[1] }] };
  },
  { annotations: { readOnlyHint: true } },
);

export const nova = createSdkMcpServer({ name: "nova", version: "1.0.0", tools: [kbSearch] });

import { query } from "@anthropic-ai/claude-agent-sdk";
import { nova } from "./kb.js";

for await (const msg of query({
  prompt: "Use kb_search to find how many vCPUs a lite VM has. Answer in one line.",
  options: {
    model: "claude-haiku-5-5",
    settingSources: [],
    mcpServers: { nova },
    allowedTools: ["mcp__nova__kb_search"],
    permissionMode: "dontAsk",
  },
})) {
  if (msg.type === "assistant") {
    for (const block of msg.message.content) if (block.type === "tool_use") console.log("tool call:", block.name);
  }
  if (msg.type === "result") {
    console.log("denied:", msg.permission_denials.map((d) => d.tool_name));
    if (msg.subtype === "success") console.log("said:", msg.result);
  }
}

