// src/kb.ts (added)
import { appendFile } from "node:fs/promises";

export const postProgress = tool(
  "post_progress",
  "Post one short progress update for the person who asked for this work.",
  { text: z.string().max(200).describe("One or two sentences, plain words") },
  async ({ text }) => {
    await appendFile("progress.log", `${new Date().toISOString()} ${text}\n`);
    return { content: [{ type: "text", text: "posted" }] };
  },
);

export const nova = createSdkMcpServer({ name: "nova", version: "1.0.0", tools: [kbSearch, postProgress] });

// test/kb.test.ts (added)
test("post_progress refuses a wall of text before the handler runs", async () => {
  const shape = z.object(postProgress.inputSchema);
  assert.equal(shape.safeParse({ text: "x".repeat(500) }).success, false);
});

